/// <summary>
/// MPJ_5013_ExciseRegisterEntry
/// Service class to run the update and creation of new record
/// </summary>
class METUpdateExciseRegisterService extends SysOperationServiceBase
{
    str                 errorMessage,infologMessage;
    utcdatetime         fromDateTime,toDateTime;

    //TODO Delete below variables after demo <start>
    SalesId             salesId;
    InventTransferId    transferId;
}

Method.Source:
    //TODO Delete below variables after demo <end>
    
    /// <summary>
    /// MPJ_5013_ExciseRegister
    /// Processes the Invoiced Sales order and creates entries in Excise Register accordingly
    /// </summary>
    /// <param name = "_contract">METUpdateExciseRegisterContract class for Sales Id input</param>
    public void processOperation(METUpdateExciseRegisterContract _contract)
    {
        VendParameters vendParameters = VendParameters::find();

        salesId = _contract.parmSalesId();
        transferId = _contract.parmTransferId();

        fromDateTime = vendParameters.METExciseRegisterTransferRunDateTime;
        toDateTime   = DateTimeUtil::utcNow();

        //TODO Delete below code after demo <start>
        if(transferId)
        {
            fromDateTime = utcDateTimeNull();
        }
        //TODO Delete code after demo <end>

        try
        {
            ttsbegin;
            
            this.processRegisterEntryForTransfer();

            if(!transferId)
            {
                vendParameters.selectForUpdate(true);
                vendParameters.METExciseRegisterTransferRunDateTime = toDateTime;
                vendParameters.update();
            }
            ttscommit;
        }
        catch
        {
            this.getErrorLog();
        }

        fromDateTime = vendParameters.METExciseRegisterSORunDateTime;
        toDateTime   = DateTimeUtil::utcNow();

        //TODO Delete below code after demo
        if(salesId)
        {
            fromDateTime = utcDateTimeNull();
        }
        //TODO Delete code after demo <end>

        try
        {
            ttsbegin;
            
            this.processRegisterEntryForPOReturns();
            this.processExciseRegisterEntryForSO();

            if(!salesId)
            {
                vendParameters.selectForUpdate(true);
                vendParameters.METExciseRegisterSORunDateTime = toDateTime;
                vendParameters.update();
            }
            ttscommit;
        }
        catch
        {
            this.getErrorLog();
        }

        fromDateTime = vendParameters.METExciseRegisterInventoryRunDateTime;
        toDateTime   = DateTimeUtil::utcNow();

        try
        {
            ttsbegin;
            
            this.processRegisterEntryForInventoryAdjustments();
            vendParameters.selectForUpdate(true);
            vendParameters.METExciseRegisterInventoryRunDateTime = toDateTime;
            vendParameters.update();
            
            ttscommit;
        }
        catch
        {
            this.getErrorLog();
        }
    }

private void getErrorLog()
{
    //If an error occurs, check if log header is available
    this.getInfologMessage();
    System.Exception ex = CLRInterop::getLastException();
    errorMessage += ex.Message + ex.ToString();
    info(errorMessage + infologMessage);
}

    private void processRegisterEntryForInventoryAdjustments()
    {
        InventJournalTable  journalTable;
        InventJournalTrans  journalTrans;
        InventDim           inventDim;
        InventSite          InventSite;

        while select journalTable
            where journalTable.Posted         == NoYes::Yes
            &&    journalTable.JournalType    == InventJournalType::LossProfit
            &&    journalTable.PostedDateTime >= fromDateTime
            &&    journalTable.PostedDateTime <  toDateTime

            join journalTrans
                where journalTrans.JournalId == journalTable.JournalId
                &&    journalTrans.Qty       != 0

            join InventSiteId from inventDim
                where inventDim.inventDimId == journalTrans.InventDimId

            join SiteId from InventSite
                where InventSite.SiteId             == inventDim.InventSiteId
                   && InventSite.MetBondedWarehouse == NoYes::Yes
        {
            if(journalTrans.Qty >0)
            {
                this.createExciseRegisterEntry(METOriginType::ItemAdjustment, journalTable.JournalId, '',journalTrans.ItemId,journalTrans.Qty,journalTrans.Unit,InventSite.SiteId,NoYes::Yes,NoYes::No,'',journalTrans.CountingReasonCode);
            }
            else
            {
                this.createExciseRegisterEntry(METOriginType::ItemAdjustment, journalTable.JournalId, '',journalTrans.ItemId,-journalTrans.Qty,journalTrans.Unit,InventSite.SiteId,NoYes::Yes,NoYes::Yes,'',journalTrans.CountingReasonCode);
            }
        }
    }

    private void processRegisterEntryForPOReturns()
    {
        InventSite              inventSite;
        VendInvoiceTrans        vendInvoiceTrans;
        InventDim               inventDim;
        
        while select InventDimId,Qty,PurchUnit,ItemId from vendInvoiceTrans
                    where   vendInvoiceTrans.Qty < 0 
                    &&      vendInvoiceTrans.CreatedDateTime >= fromDateTime
                    &&      vendInvoiceTrans.CreatedDateTime <  toDateTime
                join InventSiteId from inventDim
                    where inventDim.inventDimId == vendInvoiceTrans.InventDimId
                join SiteId from InventSite
                    where InventSite.SiteId             == inventDim.InventSiteId
                       && InventSite.MetBondedWarehouse == NoYes::Yes
        {
            this.createExciseRegisterEntry(METOriginType::PurchaseOrderReturn, vendInvoiceTrans.PurchID, vendInvoiceTrans.InvoiceId,vendInvoiceTrans.ItemId,vendInvoiceTrans.Qty,vendInvoiceTrans.PurchUnit,InventSite.SiteId,NoYes::Yes,NoYes::Yes);//change qty sign for outgoing entry
        }


    }

    /// <summary>
    /// create Excise Register Entry for Transfer Orders
    /// </summary>
    private void processRegisterEntryForTransfer()
    {
        InventTransferTable     transferTable;
        InventTransferLine      transferLine;
        METExciseRegisterEntry  metExciseRegisterEntry;
            
        while select transferTable
                    where transferTable.TransferStatus == InventTransferStatus::Received
                      &&  ( transferId == '' || (transferId != '' && transferTable.TransferId == transferId)) //TODO Delete this after Demo
            join transferLine
                   where transferLine.TransferId == transferTable.TransferId
                   &&    transferLine.ReceiveDate >= DateTimeUtil::date(fromDateTime) // we just have receive date and not time for receiving, so we will do a exists join as well
                   &&    transferLine.receiveTransDateTime() < toDateTime
            notexists join metExciseRegisterEntry
                    where metExciseRegisterEntry.OriginType         == METOriginType::TransferOrder
                       && metExciseRegisterEntry.OriginNumber       == transferLine.TransferId           //TrasferId should help in finding the duplicate records
                       && metExciseRegisterEntry.ItemId             == transferLine.ItemId
                       && metExciseRegisterEntry.CreatedDateTime    >= transferLine.receiveTransDateTime()//datetime filter to add performance by limiting records
        {
            InventSite      inventSiteFrom,inventSiteTo;
            InventLocation  inventLocation;

            select firstonly InventSiteId from inventLocation
                    where inventLocation.InventLocationId == transferTable.InventLocationIdFrom
                join SiteId,METBondedWarehouse from inventSiteFrom
                    where inventSiteFrom.SiteId             == inventLocation.InventSiteId;

            select firstonly InventSiteId from inventLocation
                    where inventLocation.InventLocationId == transferTable.InventLocationIdTo
                join SiteId,METBondedWarehouse from inventSiteTo
                    where inventSiteTo.SiteId               == inventLocation.InventSiteId;

            //if both From and To Sites are bonded sites, we dont want it to reflet on NAT30/40 reports, so make the entries transaction exempt to true
            //if only From is bonded and to is not bonded, it should have impact on NAT30/40 report, set transaction exempt to false
            //if only TO site is bonded, should never be the case

            if(inventSiteFrom.METBondedWarehouse && inventSiteTo.METBondedWarehouse && InventSiteFrom.SiteId != inventSiteTo.SiteId)
            {
                //Register for Outgoing Site, we can have multiple lines created for 1 transfer lines depending on settlement.
                this.createExciseRegisterEntry(METOriginType::TransferOrder,transferLine.TransferId,'',transferLine.ItemId,- transferLine.QtyShipped,transferLine.UnitId,inventSiteFrom.SiteId,NoYes::Yes,NoYes::Yes);//make sign -ve of qty for outgoing entry
                
                //create incoming lines with same number of lines as outgoing and same lodgment details
                METExciseRegisterEntry metExciseRegisterEntryTransferOrderOutgoing;

                while select OriginNumber, ItemId, Quantity, ReceiptUnitOfMeasure, Lodgement 
                    from  metExciseRegisterEntryTransferOrderOutgoing
                    where metExciseRegisterEntryTransferOrderOutgoing.OriginType    == METOriginType::TransferOrder
                       && metExciseRegisterEntryTransferOrderOutgoing.OriginNumber  == transferLine.TransferId
                       && metExciseRegisterEntryTransferOrderOutgoing.ItemId        == transferLine.ItemId
                       && metExciseRegisterEntryTransferOrderOutgoing.Site          == inventSiteFrom.SiteId
                {
                    //change qty(reverse sign) , site
                    this.createExciseRegisterEntry(METOriginType::TransferOrder,metExciseRegisterEntryTransferOrderOutgoing.OriginNumber,'',metExciseRegisterEntryTransferOrderOutgoing.ItemId,- metExciseRegisterEntryTransferOrderOutgoing.Quantity,metExciseRegisterEntryTransferOrderOutgoing.ReceiptUnitOfMeasure,inventSiteTo.SiteId,NoYes::No,NoYes::Yes,metExciseRegisterEntryTransferOrderOutgoing.Lodgement);
                }
            }
            else if(inventSiteFrom.METBondedWarehouse && ! inventSiteTo.METBondedWarehouse && InventSiteFrom.SiteId != inventSiteTo.SiteId)
            {
                //Register for Outgoing Site
                this.createExciseRegisterEntry(METOriginType::TransferOrder,transferLine.TransferId,'',transferLine.ItemId,- transferLine.QtyShipped,transferLine.UnitId,inventSiteFrom.SiteId,NoYes::Yes);//make sign -ve of qty for outgoing entry
            }
        }
    }

    /// <summary>
    /// create Excise Register Entry for Sales Order invoice
    /// </summary>
    private void processExciseRegisterEntryForSO()
    {
        InventSite             inventSite;
        CustInvoiceJour        custInvoiceJour;
        CustInvoiceTrans       custInvoiceTrans;
        InventDim              inventDim;

        while select SalesId, InvoiceId from custInvoiceJour
                    where custInvoiceJour.CreatedDateTime >= fromDateTime
                    &&    custInvoiceJour.CreatedDateTime <  toDateTime
                    &&  ( salesId == '' || (salesId != '' && custInvoiceJour.SalesId == salesId)) //TODO Delete this after Demo
                join InventDimId,Qty,SalesUnit,ItemId from custInvoiceTrans
                    where custInvoiceTrans.SalesId == custInvoiceJour.SalesId
                join InventSiteId from inventDim
                    where inventDim.inventDimId == custInvoiceTrans.InventDimId
                join SiteId from InventSite
                    where InventSite.SiteId             == inventDim.InventSiteId
                       && InventSite.MetBondedWarehouse == NoYes::Yes
            
        {
            if(custInvoiceTrans.Qty >0)
            {
                //Sales Order
                this.createExciseRegisterEntry(METOriginType::SalesOrder, custInvoiceJour.SalesId, custInvoiceJour.InvoiceId,custInvoiceTrans.ItemId,-custInvoiceTrans.Qty,custInvoiceTrans.SalesUnit,InventSite.SiteId,NoYes::Yes);//change qty sign for outgoing entry
            }
            else
            {
                //Sales Return
                this.createExciseRegisterEntry(METOriginType::SalesOrderReturn, custInvoiceJour.SalesId, custInvoiceJour.InvoiceId,custInvoiceTrans.ItemId,-custInvoiceTrans.Qty,custInvoiceTrans.SalesUnit,InventSite.SiteId,NoYes::No);//change qty sign for incoming entry
            }
            
        }
        
    }

    /// <summary>
    /// Create Excise Register Entries
    /// </summary>
    /// <param name = "_metOriginType">MET Origin Type enum value</param>
    /// <param name = "_metOriginId">MET Origin Id like salesId</param>
    /// <param name = "_metOriginDocumentNumber">Origin Document Number like InvoiceId</param>
    /// <param name = "_itemId">Item Id</param>
    /// <param name = "_transactionQty">Quantity , send +ve for outgoing and +ve for incoming entries</param>
    /// <param name = "_transactionUnitId">Transaction Unit ID </param>
    /// <param name = "_siteId">Site Id</param>
    /// <param name = "_isOutgoingEntry">Is Incoming or outgoing entry</param>
    /// <param name = "_customerExempt">Is transaction exempted from including in NAT30/40 report</param>
    /// <param name = "_metLodgement">Lodgement Id if available</param>
    /// <param name = "_reasonCode">reason code description</param>
    private void createExciseRegisterEntry(METOriginType _metOriginType, METOriginNumber _metOriginId, METOriginDocumentNumber _metOriginDocumentNumber, ItemId _itemId, Qty _transactionQty,InventUnitId _transactionUnitId, InventSiteId _siteId, NoYesId _isOutgoingEntry,NoYesId _customerExempt = NoYes::No,METLodgement _metLodgement = '', Description _reasonCode='')
    {
        METExciseRegisterEntry metExciseRegisterEntry;

        metExciseRegisterEntry.OriginType               = _metOriginType;
        metExciseRegisterEntry.OriginNumber             = _metOriginId;
        metExciseRegisterEntry.OriginDocumentNumber     = _metOriginDocumentNumber;
        
        metExciseRegisterEntry.ReceiptUnitOfMeasure     = _transactionUnitId;
        metExciseRegisterEntry.ItemId                   = _itemId;
        metExciseRegisterEntry.Site                     = _siteId;
        metExciseRegisterEntry.CustomerExempt           = _customerExempt;
        metExciseRegisterEntry.ReasonCode               = _reasonCode;

        metExciseRegisterEntry.ReceiptQuantity          = _transactionQty; //sales/outgoing entry will have -ve qty in register entry

        if(_isOutgoingEntry)
        {
            //we need to settle outgoing entries
            metExciseRegisterEntry.setInventUnitQty(); //calculate inventory qty for settlement

            //Create Excise Register Entries untill all the Outgoing Units/qty is consumed or there are no more entries available for consumption
            while(metExciseRegisterEntry.Quantity != 0)
            {
                metExciseRegisterEntry.Quantity = this.settleExciseRegisterEntryOutgoing(metExciseRegisterEntry);
            }

        }
        else
        {
            //update Available Quantities
            metExciseRegisterEntry.setAvailableQty();

            if(_metLodgement)
            {
                metExciseRegisterEntry.Lodgement = _metLodgement;
            }
            else
            {
                //find suitable lodgement number if not already assigned
                metExciseRegisterEntry.Lodgement = this.getLodgementDetailsForIncoming(_siteId,_itemId);
            }

            metExciseRegisterEntry.insert();
        }
    }

    /// <summary>
    /// Get Lodgment Details for a Return Sales Order
    ///    check for latest open Purchase Entry which is under consumption, use that as lodgment details
    ///    - If no open purchase found, use the latest closed entry line for lodgement details
    /// </summary>
    /// <param name = "_siteId">SiteId</param>
    /// <param name = "_itemId">ItemId</param>
    /// <returns>excise register record for lodgement reference</returns>
    private METLodgement getLodgementDetailsForIncoming(InventSiteId _siteId,ItemId _itemId)
    {
        METExciseRegisterEntry metExciseRegisterEntry;

        //find current Open excise register line for Lodgement Number which is under consumption
        metExciseRegisterEntry = this.findOldestExciseRegisterEntry(_itemId,_siteId,METOriginType::PurchaseOrder,NoYes::No);
        if(metExciseRegisterEntry.Recid)
        {
            return metExciseRegisterEntry.Lodgement;
        }
        
        //if open line not found, find the latest closed line
        select firstonly Lodgement from metExciseRegisterEntry
        order by metExciseRegisterEntry.CreatedDateTime desc
        where  (metExciseRegisterEntry.OriginType   == METOriginType::PurchaseOrder || metExciseRegisterEntry.OriginType   == METOriginType::TransferOrder)
            && metExciseRegisterEntry.Site        == _siteId
            && metExciseRegisterEntry.ItemId      == _itemId
            && metExciseRegisterEntry.Closed      == NoYes::Yes;

        //shouldn't be blank as we will always have atleast 1 purchase line before sales
        return metExciseRegisterEntry.Lodgement;
    }

    /// <summary>
    /// Create new record for Sales Order and update the consumed Purchase Order record in the Excise Register table
    /// </summary>
    /// <param name = "_metExciseRegisterEntry">base Excise register data to be created</param>
    /// <returns>remaining qty available from Sales Order that can be settled against another purchase/return sales order</returns>
    private SalesQty settleExciseRegisterEntryOutgoing(METExciseRegisterEntry _metExciseRegisterEntry)
    {
        METExciseRegisterEntry METExciseRegisterEntryInsert = _metExciseRegisterEntry.data();//copy data into new record (dont make changes in the variable record)

        //find the record against which SO quantity to be settled against.
        METExciseRegisterEntry metExciseRegisterEntryPurchase = this.findExciseRegisterEntryForSettlement(METExciseRegisterEntryInsert.ItemId,METExciseRegisterEntryInsert.Site);
        
        SalesQty availableQtyToSettle;

        if(metExciseRegisterEntryPurchase.RecId)
        {
            metExciseRegisterEntryPurchase.selectForUpdate(true);

            METExciseRegisterEntryInsert.Lodgement = metExciseRegisterEntryPurchase.Lodgement;
            
            //IF Settlement (+ve qty) record has more available quantity than the SO qty, subtract SO quantity from the available quantity of Settlement record
            if(metExciseRegisterEntryPurchase.AvailableQuantity >= abs(METExciseRegisterEntryInsert.Quantity))
            {
                metExciseRegisterEntryPurchase.AvailableQuantity = metExciseRegisterEntryPurchase.AvailableQuantity + METExciseRegisterEntryInsert.Quantity;
                metExciseRegisterEntryPurchase.Closed = metExciseRegisterEntryPurchase.AvailableQuantity==0? NoYes::Yes : NoYes::No;
                metExciseRegisterEntryPurchase.update();
                availableQtyToSettle = 0;
            }
            else
            {
                //IF Settlement (+ve qty) record has less available qty, make availabl qty 0 and close the current settlement record.
                //Carry forward the remaining SO qty to settle against the next Settlement record
                METExciseRegisterEntryInsert.Quantity = - metExciseRegisterEntryPurchase.AvailableQuantity;

                availableQtyToSettle = _metExciseRegisterEntry.Quantity + metExciseRegisterEntryPurchase.AvailableQuantity;
                metExciseRegisterEntryPurchase.AvailableQuantity = 0;
                metExciseRegisterEntryPurchase.Closed = NoYes::Yes;
                metExciseRegisterEntryPurchase.update();
            }
            
            METExciseRegisterEntryInsert.insert();
        }
        return availableQtyToSettle;
    }

    /// <summary>
    /// Find the Excise Register Record against which we need to settle the SO qty
    ///     Return Sales Order is preferred over Purchase order even if Purchase order was previously consumed.
    /// </summary>
    /// <param name = "_itemId">Item Id</param>
    /// <param name = "_site">Site Id</param>
    /// <returns>METExciseRegisterEntry record</returns>
    private METExciseRegisterEntry findExciseRegisterEntryForSettlement(ItemId _itemId,InventSiteId _site)
    {
        METExciseRegisterEntry metExciseRegisterEntry;

        //find Return Sales order entry for Settlement first
        metExciseRegisterEntry = this.findOldestExciseRegisterEntry(_itemId,_site,METOriginType::SalesOrderReturn,NoYes::No);

        if(metExciseRegisterEntry)
        {
            return metExciseRegisterEntry;
        }

        //find oldest open Purchase order entry for Settlement first
        metExciseRegisterEntry = this.findOldestExciseRegisterEntry(_itemId,_site,METOriginType::PurchaseOrder,NoYes::No);

        return metExciseRegisterEntry;
    }

    /// <summary>
    /// Find the Excise Register Record against which we need to settle the SO qty based on Origin Type
    /// </summary>
    /// <param name = "_itemId">Item Id</param>
    /// <param name = "_site">Site Id</param>
    /// <param name = "_OriginType">Origin Type</param>
    /// <param name = "_isClosed">Is Excise Register line closed</param>
    /// <returns>METExciseRegisterEntry record</returns>
    private METExciseRegisterEntry findOldestExciseRegisterEntry(ItemId _itemId,InventSiteId _site,METOriginType _OriginType, NoYes _isClosed)
    {
        METExciseRegisterEntry metExciseRegisterEntry;

        if(_OriginType == METOriginType::SalesOrderReturn)
        {
            select firstonly metExciseRegisterEntry
                order by createdDateTime asc
                where metExciseRegisterEntry.Site       == _site
                   && metExciseRegisterEntry.ItemId     == _itemId
                   && metExciseRegisterEntry.Closed     == _isClosed
                   && metExciseRegisterEntry.OriginType == _OriginType
                   && metExciseRegisterEntry.Quantity   > 0;
        }
        else
        {
            select firstonly metExciseRegisterEntry
                order by createdDateTime asc
                where metExciseRegisterEntry.Site       == _site
                   && metExciseRegisterEntry.ItemId     == _itemId
                   && metExciseRegisterEntry.Closed     == _isClosed
                   && (
                        metExciseRegisterEntry.OriginType == METOriginType::PurchaseOrder
                     || metExciseRegisterEntry.OriginType == METOriginType::TransferOrder
                    )
                   && metExciseRegisterEntry.Quantity   > 0;
        }
        return metExciseRegisterEntry;
    }

    /// <summary>
    /// Copied from MPJ_5046_MetpayInterfaces 05/05/2021
    /// This method gets the info of the error into a variable
    /// </summary>
    private void getInfologMessage()
    {
        SysInfologEnumerator sysInfologEnumerator;
        SysInfologMessageStruct sysInfologMessageStruct;
        errorMessage    = '';
        infologMessage  = '';
        sysInfologEnumerator = SysInfologEnumerator::newData(infolog.infologData());

        while (sysInfologEnumerator.moveNext())
        {
            sysInfologMessageStruct = new SysInfologMessageStruct(sysInfologEnumerator.currentMessage());

            if (sysInfologEnumerator.currentException() == Exception::Error)
            {
                errorMessage += strfmt(sysInfologMessageStruct.message());
            }
            infologMessage += strfmt(sysInfologMessageStruct.message());
        }
    }
